function bindPurchaseActions(root=document){root.querySelectorAll('[data-edit-purchase]').forEach(b=>b.onclick=()=>{const p=finance.purchases.find(x=>x.id===b.dataset.editPurchase);if(!p)return;quickForm('Edit transaction','Merchant,Amount,Date,Category,Card (optional)',async([merchant,amount,date,category,cardName])=>{const oldCard=finance.cards.find(c=>c.name===p.card),newCard=finance.cards.find(c=>c.name===cardName);if(oldCard)oldCard.balance=Math.max(0,Number(oldCard.balance||0)-Number(p.amount||0));Object.assign(p,{merchant:merchant.trim(),amount:Number(amount),date,category:category.trim()||'Other',card:cardName});if(newCard)newCard.balance=Number(newCard.balance||0)+p.amount;await save();render($('#page-title').textContent)},{Merchant:p.merchant,Amount:p.amount,Date:p.date,Category:p.category,'Card (optional)':p.card||''})});root.querySelectorAll('[data-remove-purchase]').forEach(b=>b.onclick=async()=>{const p=finance.purchases.find(x=>x.id===b.dataset.removePurchase);if(!p||!confirm(`Remove the ${p.merchant} transaction?`))return;const card=finance.cards.find(c=>c.name===p.card);if(card)card.balance=Math.max(0,Number(card.balance||0)-Number(p.amount||0));finance.purchases=finance.purchases.filter(x=>x.id!==p.id);await save();render($('#page-title').textContent)})}
function goalsList(){const goals=finance.goals.slice(0,3);return goals.length?goals.map(g=>{const pct=Math.min(100,Math.round(Number(g.saved||0)/Math.max(1,Number(g.target||1))*100));return `<div class="goal-row"><div class="goal-top"><strong>${escapeHtml(g.name)}</strong><span>${money(g.saved)} / ${money(g.target)}</span></div><div class="goal-track"><span style="width:${pct}%"></span></div><div class="goal-meta"><span>${pct}% there</span><span>${g.date?`Target ${escapeHtml(g.date)}`:'Keep it up'}</span></div></div>`}).join(''):'<div class="empty">Set a goal and make a little progress each month.</div>'}
