function allocationItems(scope,colors){if(scope==='all')return Object.entries(investmentCategories()).map(([label,value])=>({label,value,color:colors[label]||categoryColor(label)})).filter(item=>item.value>0).sort((a,b)=>b.value-a.value);const holdings=finance.investments.filter(item=>String(item.category||'').toLowerCase()===scope.toLowerCase()),byName=new Map();holdings.forEach(item=>{const label=String(item.ticker||item.name||'Holding').trim(),current=byName.get(label);if(current)current.value+=investmentValue(item);else byName.set(label,{label,value:investmentValue(item)})});const palettes={stocks:['#4388c5','#67a2d8','#326fa8','#8bb8e2','#527fc1','#3f9ab0','#7298ca'],crypto:['#e58d45','#f3ad63','#cf7541','#f0c17a','#b96d50','#e6a653','#d8833d']};return [...byName.values()].filter(item=>item.value>0).sort((a,b)=>b.value-a.value).map((item,index)=>({...item,color:palettes[scope.toLowerCase()][index%palettes[scope.toLowerCase()].length]}))}
