function allocationPieMarkup(items,total,scope){if(!items.length||total<=0)return `<div id="allocation-pie" class="allocation-pie-wrap ${allocationView==='pie'?'':'hidden'}"><div class="allocation-empty">${scope==='all'?'Add holdings to see your allocation.':`Add ${scope.toLowerCase()} holdings to see this chart.`}</div></div>`;let angle=-90;const slices=items.map((item,index)=>{const share=item.value/total*100,end=angle+share*3.6,mid=(angle+end)/2*Math.PI/180,dx=Math.cos(mid)*7,dy=Math.sin(mid)*7,shape=items.length===1?`<circle class="allocation-slice" cx="110" cy="110" r="94" data-index="${index}" data-label="${escapeHtml(item.label)}" data-value="${item.value}" data-share="${share.toFixed(1)}" style="fill:${item.color};--slice-x:${dx}px;--slice-y:${dy}px" role="button" tabindex="0" aria-label="${escapeHtml(item.label)}: ${moneyExact(item.value)}, ${share.toFixed(1)} percent"/>`:`<path class="allocation-slice" d="${allocationDonutPath(angle,end)}" data-index="${index}" data-label="${escapeHtml(item.label)}" data-value="${item.value}" data-share="${share.toFixed(1)}" style="fill:${item.color};--slice-x:${dx}px;--slice-y:${dy}px" role="button" tabindex="0" aria-label="${escapeHtml(item.label)}: ${moneyExact(item.value)}, ${share.toFixed(1)} percent"/>`;angle=end;return shape}).join(''),scopeLabel=scope==='all'?'Portfolio':scope;return `<div id="allocation-pie" class="allocation-pie-wrap ${allocationView==='pie'?'':'hidden'}"><div class="allocation-pie-stage"><svg id="allocation-pie-chart" class="allocation-pie" viewBox="0 0 220 220" role="group" aria-label="${escapeHtml(scopeLabel)} allocation pie chart">${slices}${items.length===1?'<circle class="allocation-pie-hole" cx="110" cy="110" r="58"/>':''}</svg><div class="allocation-detail" id="allocation-detail" role="status" aria-live="polite"><span id="allocation-detail-label">${escapeHtml(scopeLabel)}</span><strong id="allocation-detail-value">${moneyExact(total)}</strong><small id="allocation-detail-share">100% of selected assets</small></div></div><div class="allocation-legend">${items.map((item,index)=>`<button type="button" class="allocation-legend-item" data-allocation-index="${index}" aria-pressed="false"><i style="background:${item.color}"></i><span>${escapeHtml(item.label)}</span><strong>${moneyExact(item.value)} <small>${(item.value/total*100).toFixed(1)}%</small></strong></button>`).join('')}</div></div>`}
function bindAllocationPie(){const chart=$('#allocation-pie-chart'),label=$('#allocation-detail-label'),value=$('#allocation-detail-value'),share=$('#allocation-detail-share');if(!chart||!label||!value||!share)return;const slices=[...chart.querySelectorAll('.allocation-slice')],legend=$$('.allocation-legend-item'),scopeName=allocationScope==='all'?'Portfolio':allocationScope,total=slices.reduce((sum,slice)=>sum+Number(slice.dataset.value||0),0);let selected=null;const show=slice=>{if(!slice)return;const index=slice.dataset.index,pct=Number(slice.dataset.share);slices.forEach(item=>item.classList.toggle('is-active',item===slice));legend.forEach(item=>{const active=item.dataset.allocationIndex===index;item.classList.toggle('is-active',active);item.setAttribute('aria-pressed',String(active&&selected===slice))});label.textContent=slice.dataset.label;value.textContent=moneyExact(Number(slice.dataset.value));share.textContent=`${pct.toFixed(1)}% of ${allocationScope==='all'?'portfolio':allocationScope.toLowerCase()}`};const reset=()=>{if(selected){show(selected);return}slices.forEach(item=>item.classList.remove('is-active'));legend.forEach(item=>{item.classList.remove('is-active');item.setAttribute('aria-pressed','false')});label.textContent=scopeName;value.textContent=moneyExact(total);share.textContent='100% of selected assets'};const attach=element=>{const slice=slices[Number(element.dataset.index??element.dataset.allocationIndex)];if(!slice)return;element.addEventListener('pointerenter',()=>show(slice));element.addEventListener('pointerleave',reset);element.addEventListener('focus',()=>show(slice));element.addEventListener('blur',reset);element.addEventListener('click',()=>{selected=selected===slice?null:slice;reset()});if(element.tagName.toLowerCase()==='path'||element.tagName.toLowerCase()==='circle')element.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();element.click()}})};slices.forEach(attach);legend.forEach(attach)}
